from lib import *
S = SS('x37')
steps = [
    step("一个事务管理器只管一个数据源。同一个 MySQL 实例里的两个库 A 与 B,各配一个 DataSource 和一个事务管理器。(0)@Transactional(txA) 写 A 和 B,成功:两库各 1 行,一致。(1)同样的方法最后抛异常:A 库 0 行、B 库 1 行,不一致——txA 只管 A,B 的写入是自动提交的,不会回滚。(2)嵌套模板 A 外 B 内都成功:一致。(3)B 内层先提交,之后 A 外层抛异常:A 0 行、B 1 行,不一致。(4)A 在提交前连接被杀(B 已先提交):A 的提交失败,抛 TransactionSystemException,A 0 行、B 1 行,不一致。(5)换成 B 外 A 内,A 的连接在 A 提交前被杀:A 的提交异常冒到外层,B 跟着回滚,两库都是 0 行,一致。(6)B 外 A 内、A 先提交,B 的连接在 B 提交前被杀:A 1 行、B 0 行,不一致。谁先提交谁就已经落盘,后提交的失败了,前面的撤销不了。", t=tl(S(1)), mark=lidx(S(1), '(1)@Transactional(txA)', '(3)嵌套模板', '(4)嵌套模板', '(6)B 外 A 内'), done=lidx(S(1), '(0)@Transactional(txA) 写 A 和 B,成功', '(2)嵌套模板:A 外 B 内,都成功', '(5)反过来'), b=bars([['一致的场景个数', 3, '3:(0)(2)(5)'], ['不一致的场景个数', 4, '4:(1)(3)(4)(6)'], ['场景总数', 7, '7']], 7, done=[0], mark=[1], cur=[2]), kv=KV([['txA 只管 A', 'B 的写入不回滚'], ['先提交的', '已经落盘,撤销不了'], ['后提交的失败', '前面已提交的那边留下数据'], ['(5)一致只是运气', '失败的恰好是先提交的那一个']], ['(5)一致只是运气'])),
]
A = mkartx('x37', 37, 'Spring,事务,多数据源,分布式事务,最终一致,真实验证,动画演示',
    '实测多数据源下一个事务管理器只管一个数据源:@Transactional(txA) 写 A 和 B 后抛异常,A 回滚而 B 留下 1 行;嵌套模板先提交的一方撤销不了,后提交的失败会让两库不一致(七个场景里 4 个不一致);只有恰好是先提交的那一方失败时才碰巧一致。',
    '同一个服务里写两个数据库,一个 @Transactional 管得住吗?嵌套两个事务模板呢?提交时一方失败会怎样?这篇在 Spring Framework 7.0.9 和 MySQL 26.7.0 上用杀连接制造提交失败,逐个量出来。',
    [('7 个里 4 个', '多数据源的七个场景中两库行数不一致的个数'), ('A 0 行,B 1 行', '@Transactional(txA) 写 A 和 B 后抛异常的结果'), ('A 1 行,B 0 行', 'B 外 A 内、A 先提交、B 提交前连接被杀的结果')],
    [('事务管理器只管自己的数据源', '<p>一个方法同时写两个库,另一个库的写入不受 @Transactional 控制,不会回滚。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 + 两个 DataSourceTransactionManager + HikariCP + 自己起的 MySQL 26.7.0(同一个实例里的 demo 与 demo2 两个库);提交失败是通过另一个连接对要提交的连接执行 KILL 制造的(第 4、5、6 个场景),不是真实的网络故障;场景 4 到 6 的异常链最底层的异常类型(SQLNonTransientConnectionException 或 EOFException)取决于被杀连接的状态,每次运行可能不同',
     '没有验证:XA / JTA 两阶段提交(见分布式事务系列);Spring Data 里已经移除的 ChainedTransactionManager;最大努力一次提交(best effort 1PC)之外的补偿方案(Saga、Outbox,见分布式事务系列);两个库在不同 MySQL 实例上的情形(这里是同一个实例里的两个库,故障模型一样但没有验证)'],
    '多数据源事务的边界')
